	for (var i=0; i<selectedTrans.listLength; i++) {
		tw.local.sqlStatements[i] = new tw.object.SQLStatement()
		
		if(!tw.local.refresh)
			tw.local.sqlStatements[i].sql = "SELECT ACCOUNTNO, TRANSACTIONREFNO, AMOUNTLINKEDINBPM, POSTINGDATE FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE TRANSACTIONREFNO = ? AND ACCOUNTNO = ? ORDER BY ID DESC FETCH FIRST 1 ROW ONLY FOR UPDATE;"
		else
			tw.local.sqlStatements[i].sql = "SELECT ACCOUNTNO, TRANSACTIONREFNO, AMOUNTLINKEDINBPM, POSTINGDATE FROM "+tw.env.LKP_DB_Schema+".ODC_FCTRANSACTION WHERE TRANSACTIONREFNO = ? AND ACCOUNTNO = ? ORDER BY ID DESC FETCH FIRST 1 ROW ONLY;"
		tw.local.sqlStatements[i].parameters = new tw.object.listOf.SQLParameter();
		tw.local.sqlStatements[i].parameters[0] = new tw.object.SQLParameter();
		tw.local.sqlStatements[i].parameters[0].value = selectedTrans[i].referenceNumber;
		tw.local.sqlStatements[i].parameters[1] = new tw.object.SQLParameter();
		tw.local.sqlStatements[i].parameters[1].value = selectedTrans[i].accountNo;
	}
}


